From 130b52316f0d128b8c9a1ada2cb1bc7b8a4e476a Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 02:44:21 +0100
Subject: [PATCH] wayland: don't give the lock screen access to the clipboard

The screen locker could bind the data device and primary selection
managers, so Ctrl+V or a middle click in the password field pasted the
session's clipboard. Hide both globals from the screen locker's client.

BUG: 503596
---
 src/wayland_server.cpp | 8 ++++++++
 1 file changed, 8 insertions(+)

diff --git a/src/wayland_server.cpp b/src/wayland_server.cpp
index e83c6adcb8..f7f2886ddd 100644
--- a/src/wayland_server.cpp
+++ b/src/wayland_server.cpp
@@ -144,6 +144,10 @@ public:
         QByteArrayLiteral("zwp_xwayland_keyboard_grab_manager_v1"),
         QByteArrayLiteral("xwayland_shell_v1"),
     };
+    const QSet<QByteArray> clipboardInterfaces = {
+        QByteArrayLiteral("wl_data_device_manager"),
+        QByteArrayLiteral("zwp_primary_selection_device_manager_v1"),
+    };

     bool allowInterface(ClientConnection *client, const QByteArray &interfaceName) override
     {
@@ -151,6 +155,10 @@ public:
             return false;
         }

+        if (client == waylandServer()->screenLockerClientConnection() && clipboardInterfaces.contains(interfaceName)) {
+            return false;
+        }
+
         if (client == waylandServer()->inputMethodConnection()) {
             return true;
         } else if (inputmethodInterfaces.contains(interfaceName)) {
-- 
